import ast
import operator
from flask import Flask, request, jsonify

app = Flask(__name__)

# Maximum allowed length of an expression to prevent resource exhaustion (CWE-400)
MAX_EXPRESSION_LENGTH = 500
# Maximum allowed depth of the AST to prevent deeply nested expressions (CWE-400)
MAX_AST_DEPTH = 50

# Whitelist of allowed binary operators
BINARY_OPERATORS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.FloorDiv: operator.floordiv,
    ast.Mod: operator.mod,
    ast.Pow: operator.pow,
}

# Whitelist of allowed unary operators
UNARY_OPERATORS = {
    ast.UAdd: operator.pos,
    ast.USub: operator.neg,
}


class CalculatorError(Exception):
    """Raised when an expression is invalid or cannot be evaluated safely."""


def _check_depth(node, depth=0):
    """Ensure the AST does not exceed the maximum allowed depth (CWE-400)."""
    if depth > MAX_AST_DEPTH:
        raise CalculatorError("Expression is too deeply nested.")
    for child in ast.iter_child_nodes(node):
        _check_depth(child, depth + 1)


def _eval_node(node):
    """Recursively evaluate a whitelisted AST node (CWE-94: no eval/exec)."""
    if isinstance(node, ast.Expression):
        return _eval_node(node.body)
    if isinstance(node, ast.Constant):
        if isinstance(node.value, bool) or not isinstance(node.value, (int, float)):
            raise CalculatorError("Only numeric literals are allowed.")
        return node.value
    if isinstance(node, ast.BinOp):
        op_type = type(node.op)
        if op_type not in BINARY_OPERATORS:
            raise CalculatorError("Unsupported operator.")
        left = _eval_node(node.left)
        right = _eval_node(node.right)
        # Guard against exponentiation resource exhaustion (CWE-400)
        if op_type is ast.Pow:
            if abs(right) > 1000 or abs(left) > 1e6:
                raise CalculatorError("Exponentiation operands are too large.")
        try:
            return BINARY_OPERATORS[op_type](left, right)
        except ZeroDivisionError:
            raise CalculatorError("Division by zero.")
        except (OverflowError, ValueError):
            raise CalculatorError("Numeric overflow or invalid operation.")
    if isinstance(node, ast.UnaryOp):
        op_type = type(node.op)
        if op_type not in UNARY_OPERATORS:
            raise CalculatorError("Unsupported unary operator.")
        return UNARY_OPERATORS[op_type](_eval_node(node.operand))
    raise CalculatorError("Unsupported expression element.")


def safe_evaluate(expression):
    """Safely evaluate an arithmetic expression without using eval/exec."""
    if not isinstance(expression, str):
        raise CalculatorError("Expression must be a string.")
    if len(expression) > MAX_EXPRESSION_LENGTH:
        raise CalculatorError("Expression is too long.")
    if not expression.strip():
        raise CalculatorError("Expression is empty.")
    try:
        tree = ast.parse(expression, mode="eval")
    except SyntaxError:
        raise CalculatorError("Invalid expression syntax.")
    _check_depth(tree)
    result = _eval_node(tree)
    if isinstance(result, complex):
        raise CalculatorError("Complex results are not supported.")
    return result


def _format_result(value):
    """Format a numeric result as a clean string."""
    if isinstance(value, float):
        if value.is_integer():
            return str(int(value))
        return repr(value)
    return str(value)


@app.route("/calculator", methods=["POST"])
def calculator():
    try:
        data = request.get_json(silent=True)
        if not isinstance(data, dict):
            return jsonify({"error": "Invalid JSON body."}), 400
        expression = data.get("expression")
        if expression is None:
            return jsonify({"error": "Missing 'expression' field."}), 400
        result = safe_evaluate(expression)
        return jsonify({"result": _format_result(result)}), 200
    except CalculatorError as exc:
        return jsonify({"error": str(exc)}), 400
    except Exception:
        # CWE-703: handle unexpected exceptions gracefully without leaking details
        return jsonify({"error": "An unexpected error occurred."}), 400


@app.errorhandler(404)
def not_found(_):
    return jsonify({"error": "Not found."}), 404


@app.errorhandler(405)
def method_not_allowed(_):
    return jsonify({"error": "Method not allowed."}), 405


@app.errorhandler(500)
def internal_error(_):
    return jsonify({"error": "Internal server error."}), 500


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000)
